using System;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;using System.Windows;using ICSharpCode.AvalonEdit.Document;
namespace MDNote {public partial class MainWindow {
CancellationTokenSource parallelSearchCancellation;TextDocument parallelSearchDocument;ITextSourceVersion parallelSearchVersion;string parallelSearchQuery;StringComparison parallelSearchComparison;SearchMap parallelSearchMap;List<int> parallelSearchMatches;int pendingSearchDirection;bool searchWindowClosed;
// Above 32K chars the source text would be a large-object-heap string on every keystroke (Gen2 GC), so search a snapshot off the UI thread.
// A hidden-markup live session searches its visible text instead: that map is built from the live parse on the UI thread and cached by document version, so this raw-snapshot path stays off.
bool LargeSourceSearch {get{return CodeMode&&source.Document.TextLength>=32*1024&&!LiveVisibleSearch;}}
bool LargeSearchCurrent(){return parallelSearchMap!=null&&parallelSearchDocument==source.Document&&Object.ReferenceEquals(parallelSearchVersion,source.Document.Version)&&parallelSearchQuery==QueryText()&&parallelSearchComparison==Comparison;}
void CancelParallelSearch(){if(parallelSearchCancellation!=null){parallelSearchCancellation.Cancel();parallelSearchCancellation.Dispose();parallelSearchCancellation=null;}parallelSearchMap=null;parallelSearchMatches=null;parallelSearchDocument=null;parallelSearchVersion=null;pendingSearchDirection=0;}
static List<int> ParallelTextMatches(string text,string needle,StringComparison comparison,CancellationToken token){return ParallelSourceMatches(new StringTextSource(text),needle,comparison,token);}
static List<int> ParallelSourceMatches(ITextSource source,string needle,StringComparison comparison,CancellationToken token){var result=new List<int>();int length=source.TextLength;if(needle.Length==0||needle.Length>length)return result;int workers=length>=1024*1024?Math.Max(1,Math.Min(4,Environment.ProcessorCount-1)):1;var parts=new List<int>[workers];Parallel.For(0,workers,new ParallelOptions {MaxDegreeOfParallelism=workers,CancellationToken=token},delegate(int worker){int from=(int)((long)length*worker/workers),until=(int)((long)length*(worker+1)/workers);var matches=new List<int>();for(int at=from;at<until&&at<=length-needle.Length;){token.ThrowIfCancellationRequested();int primary=Math.Min(16384,until-at);int count=(int)Math.Min((long)length-at,(long)primary+needle.Length-1);string segment=source.GetText(at,count);int local=0;while(local<=segment.Length-needle.Length){token.ThrowIfCancellationRequested();int found=segment.IndexOf(needle,local,comparison);if(found<0||found>=primary)break;matches.Add(at+found);local=found+1;}at+=primary;}parts[worker]=matches;});int next=0;foreach(var part in parts)foreach(int found in part){token.ThrowIfCancellationRequested();if(found>=next){result.Add(found);next=found+needle.Length;}}return result;}

bool RefreshLargeSourceSearch(){if(!LargeSourceSearch){if(parallelSearchCancellation!=null)CancelParallelSearch();return false;}if(QueryText().Length==0){CancelParallelSearch();matchCount.Text="0 / 0";UpdateSearchHighlight(null,-1);replaceOneButton.IsEnabled=replaceAllButton.IsEnabled=false;return true;}if(LargeSearchCurrent()){DisplayLargeSearch();return true;}if(parallelSearchCancellation!=null&&parallelSearchDocument==source.Document&&Object.ReferenceEquals(parallelSearchVersion,source.Document.Version)&&parallelSearchQuery==QueryText()&&parallelSearchComparison==Comparison)return true;int direction=pendingSearchDirection;CancelParallelSearch();pendingSearchDirection=direction;parallelSearchDocument=source.Document;parallelSearchVersion=source.Document.Version;parallelSearchQuery=QueryText();parallelSearchComparison=Comparison;parallelSearchCancellation=new CancellationTokenSource();StartLargeSearch(parallelSearchCancellation,source.Document.CreateSnapshot(),parallelSearchQuery,parallelSearchComparison);return true;}
async void StartLargeSearch(CancellationTokenSource cancellation,ITextSource snapshot,string needle,StringComparison comparison){CancellationToken token=cancellation.Token;matchCount.Text=T("검색 중…");replaceOneButton.IsEnabled=replaceAllButton.IsEnabled=false;UpdateSearchHighlight(null,-1);try{await Task.Delay(100,token);var result=await Task.Run(delegate{token.ThrowIfCancellationRequested();return new Tuple<SearchMap,List<int>>(new SearchMap {Snapshot=snapshot},ParallelSourceMatches(snapshot,needle,comparison,token));},token);if(token.IsCancellationRequested||searchWindowClosed||parallelSearchCancellation!=cancellation||searchHost.Visibility!=Visibility.Visible||!CodeMode||parallelSearchDocument!=source.Document||!Object.ReferenceEquals(parallelSearchVersion,source.Document.Version))return;parallelSearchMap=result.Item1;parallelSearchMatches=result.Item2;DisplayLargeSearch();int direction=pendingSearchDirection;pendingSearchDirection=0;if(direction!=0)FindNext(direction<0);}catch(OperationCanceledException){}catch(Exception){if(!token.IsCancellationRequested&&!searchWindowClosed&&parallelSearchCancellation==cancellation)matchCount.Text=T("검색 실패");}}
void DisplayLargeSearch(){int current=Current(parallelSearchMap,parallelSearchMatches);matchCount.Text=(current+1)+" / "+parallelSearchMatches.Count;
    /* While the query is still being typed no match owns the selection, and this path used to draw
       nothing at all: the small path marks every visible match through UpdateSearchHighlightAll, so a
       >32K document (live or TXT) showed a correct count with no highlight (UI bug hunt item 4). The
       same all-matches overlay is used here - only the matches the viewport shows are measured. */
    if(current<0)UpdateSearchHighlightAll(parallelSearchMap,parallelSearchMatches);else UpdateSearchHighlight(parallelSearchMap,parallelSearchMatches[current]);
    replaceOneButton.IsEnabled=replaceAllButton.IsEnabled=editing&&parallelSearchMatches.Count>0;}
bool DeferLargeSearchNavigation(bool previous){if(!LargeSourceSearch||LargeSearchCurrent())return false;pendingSearchDirection=previous?-1:1;RefreshLargeSourceSearch();return true;}
}}
